    // GET lookups
    public async Task<TprmSetsResult> LookupsAsync(TprmLookupsQuery request, TprmCaller caller, CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(request);
        try
        {
            await using var connection = await OpenAsync(cancellationToken);
            await using var command    = Proc(connection, "grac_practice.sp_tprm_lookups");
            AddParam(command, "@organization_id", DbType.Int64, request.OrganizationId);
            return await SetsAsync(command, _ => ["values", "employees", "businessFunctions", "processes", "applications", "thirdParties", "contracts", "library", "customFields", "riskModel", "dimensions", "bands", "evidenceTypes", "roles"], cancellationToken);
        }
        catch (Exception ex)
        {
            return new TprmSetsResult(false, new Dictionary<string, IReadOnlyList<Dictionary<string, object?>>>(), UserMessage(ex, "The record could not be loaded.", "sp_tprm_lookups"));
        }
    }

    // GET config/reference
    public async Task<TprmSetsResult> ConfigReferenceAsync(TprmConfigReferenceQuery request, TprmCaller caller, CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(request);
        try
        {
            await using var connection = await OpenAsync(cancellationToken);
            await using var command    = Proc(connection, "grac_practice.sp_tprm_config_reference_get");
            if (request.OrganizationId is not null) AddParam(command, "@organization_id", DbType.Int64, request.OrganizationId);
            if (!string.IsNullOrWhiteSpace(request.ListCode)) AddParam(command, "@list_code", DbType.String, Text(request.ListCode), 60);
            AddParam(command, "@is_platform_admin", DbType.Boolean, caller.IsPlatformAdmin);
            return await SetsAsync(command, _ => ["lists", "values"], cancellationToken);
        }
        catch (Exception ex)
        {
            return new TprmSetsResult(false, new Dictionary<string, IReadOnlyList<Dictionary<string, object?>>>(), UserMessage(ex, "The record could not be loaded.", "sp_tprm_config_reference_get"));
        }
    }

