            if (request.OrganizationId is not null) AddParam(command, "@organization_id", DbType.Int64, request.OrganizationId);
            if (request.ValueId is not null) AddParam(command, "@value_id", DbType.Int64, request.ValueId);
            AddParam(command, "@list_code", DbType.String, Text(request.ListCode), 60);
            AddParam(command, "@value_code", DbType.String, Text(request.ValueCode), 60);
            AddParam(command, "@label", DbType.String, Text(request.Label), 200);
            if (!string.IsNullOrWhiteSpace(request.Description)) AddParam(command, "@description", DbType.String, Text(request.Description), 1000);
            if (!string.IsNullOrWhiteSpace(request.MeaningCode)) AddParam(command, "@meaning_code", DbType.String, Text(request.MeaningCode), 40);
            if (request.RankNo is not null) AddParam(command, "@rank_no", DbType.Int32, request.RankNo);
