            AddParam(command, "@is_platform_admin", DbType.Boolean, caller.IsPlatformAdmin);
            AddParam(command, "@actor", DbType.String, caller.Actor, 100);
            return await CommandAsync(command, cancellationToken);
        }
        catch (Exception ex)
